<script setup lang="ts">
import { reactive, ref } from 'vue'
import { useRouter } from 'vue-router'
import { applicationService, type Registration } from '@/services/applications'
import AppModal from '@/components/AppModal.vue'
import { demoMode } from '@/services/quality'
const confirm=ref(false)
const router = useRouter(); const step = ref(1); const error = ref(''); const busy = ref(false)
const form = reactive<Registration>({ name: '', email: '', password: '', password_confirmation: '', officine_name: '', phone: '', city: '', address: '', applicant_function: 'Pharmacien titulaire', consent: false })
async function submit() {
 error.value = ''
 if (step.value === 1 && (form.password !== form.password_confirmation || !/[a-zA-Z]/.test(form.password) || !/\d/.test(form.password))) { error.value = 'Les mots de passe doivent être identiques et contenir des lettres et des chiffres.'; return }
 if (step.value < 3) { step.value++; return }
 if(!demoMode){confirm.value=true;return}
 await create()
}
async function create(){
 busy.value = true
 try { const id = await applicationService.register(form); form.password = ''; form.password_confirmation = ''; router.push(`/application?id=${id}`) }
 catch(e) { error.value = (e as Error).message } finally { busy.value = false }
}
</script>
<template><div class="registration-page"><header><RouterLink class="brand" to="/login">bestpharma.</RouterLink><RouterLink class="text-link" to="/login">Déjà un compte ? Se connecter</RouterLink></header><main class="registration-content"><p class="eyebrow">OUVRIR MON ESPACE OFFICINE</p><h1>Votre démarche qualité,<br><span class="accent-serif">commence ici.</span></h1><p class="page-subtitle">Un compte, votre dossier, puis l’instruction par l’équipe BEG.</p><ol class="registration-steps" aria-label="Étapes de l’inscription"><li v-for="(label, i) in ['Mon compte', 'Mon officine', 'Vérification']" :key="label" :class="{current: step === i+1, done: step > i+1}" :aria-current="step === i+1 ? 'step' : undefined"><b>{{ i+1 }}</b>{{ label }}</li></ol><form class="panel registration-form" @submit.prevent="submit"><p v-if="error" role="alert" class="alert error">{{ error }}</p><div v-if="step === 1" class="form-body"><h2>Créons votre compte.</h2><label>Nom et prénom *<input v-model.trim="form.name" autocomplete="name" maxlength="120" required /></label><label>Adresse e-mail *<input v-model.trim="form.email" type="email" autocomplete="email" maxlength="254" required /></label><div class="form-grid"><label>Mot de passe *<input v-model="form.password" type="password" autocomplete="new-password" minlength="12" maxlength="128" required /></label><label>Confirmation *<input v-model="form.password_confirmation" type="password" autocomplete="new-password" minlength="12" maxlength="128" required /></label></div><p class="field-hint">12 caractères minimum, avec des lettres et des chiffres.</p></div><div v-else-if="step === 2" class="form-body"><h2>Présentez votre officine.</h2><label>Nom de l’officine *<input v-model.trim="form.officine_name" maxlength="180" required /></label><div class="form-grid"><label>Ville *<input v-model.trim="form.city" maxlength="120" required /></label><label>Téléphone professionnel *<input v-model.trim="form.phone" type="tel" pattern="[+0-9 ()\-]{6,40}" maxlength="40" required /></label></div><label>Adresse *<input v-model.trim="form.address" maxlength="500" required /></label><label>Votre fonction *<select v-model="form.applicant_function"><option>Pharmacien titulaire</option><option>Pharmacien adjoint</option><option>Promoteur / propriétaire</option><option>Responsable qualité</option><option>Autre mandataire</option></select></label><p class="field-hint">La fonction déclarée ne confère aucune habilitation ni permission applicative automatique.</p></div><div v-else class="form-body"><h2>Vérifiez votre dossier.</h2><dl class="application-summary"><dt>Demandeur</dt><dd>{{ form.name }}</dd><dt>E-mail</dt><dd>{{ form.email }}</dd><dt>Officine</dt><dd>{{ form.officine_name }}</dd><dt>Coordonnées</dt><dd>{{ form.address }}, {{ form.city }}<br>{{ form.phone }}</dd><dt>Fonction déclarée</dt><dd>{{ form.applicant_function }}</dd></dl><label class="checkbox-label"><input v-model="form.consent" type="checkbox" required /><span>Je confirme être habilité à soumettre ce dossier. Je comprends que l’activation BestPharma ne constitue ni une autorisation d’exercice ni une certification BPD.</span></label><p class="field-hint">Aucun accès métier n’est accordé avant instruction et activation du dossier.</p></div><div class="modal-footer"><button v-if="step > 1" class="button secondary" type="button" :disabled="busy" @click="step--; error = ''">Retour</button><button class="button primary" :disabled="busy">{{ busy ? 'Enregistrement…' : step < 3 ? 'Continuer' : demoMode?'Soumettre mon dossier':'Créer mon compte et mon brouillon' }}</button></div></form><p v-if="!demoMode" class="module-disclaimer">Cette étape crée un brouillon privé. Vous devrez ensuite vérifier votre email, compléter le département et soumettre explicitement le dossier.</p></main><AppModal v-model="confirm" title="Créer mon compte et mon brouillon ?" :busy="busy"><div class="form-body"><p v-if="error" class="alert error" role="alert">{{error}}</p><p>Votre dossier ne sera pas envoyé à l’instruction avant vérification de l’email et soumission explicite. Aucun accès métier ne sera créé à cette étape.</p></div><template #footer><button class="button secondary" :disabled="busy" @click="confirm=false">Annuler</button><button class="button primary" :disabled="busy" @click="create">Confirmer la création</button></template></AppModal></div></template>
